class Solution:
    def minTravelTime(self, l: int, n: int, k: int, position: List[int], time: List[int]) -> int:
        INF = float('inf')
        T = [0] * (n + 1)
        for i in range(n):
            T[i + 1] = T[i] + time[i]
        dp = [[INF] * (k + 1) for _ in range(n)]
        dp[0][0] = 0
        for i in range(1, n):
            for j in range(min(k, i - 1) + 1):
                for p in range(i):
                    used = j - (i - p - 1)
                    if used < 0 or dp[p][used] == INF:
                        continue
                    cand = dp[p][used] + (position[i] - position[p]) * (T[i] - T[p])
                    if cand < dp[i][j]:
                        dp[i][j] = cand
        return dp[n - 1][k]

