class Solution {
public:
    int minTravelTime(int l, int n, int k, vector<int>& position, vector<int>& time) {
        const int INF = INT_MAX / 2;
        vector<long long> T(n + 1, 0);
        for (int i = 0; i < n; i++) T[i + 1] = T[i] + time[i];
        vector<vector<long long>> dp(n, vector<long long>(k + 1, INF));
        dp[0][0] = 0;
        for (int i = 1; i < n; i++)
            for (int j = 0; j <= min(k, i - 1); j++)
                for (int p = 0; p < i; p++) {
                    int used = j - (i - p - 1);
                    if (used < 0 || dp[p][used] >= INF) continue;
                    long long cand = dp[p][used] + (long long)(position[i] - position[p]) * (T[i] - T[p]);
                    dp[i][j] = min(dp[i][j], cand);
                }
        return (int) dp[n - 1][k];
    }
};

