class Solution {
    public int minTravelTime(int l, int n, int k, int[] position, int[] time) {
        final int INF = Integer.MAX_VALUE / 2;
        long[] T = new long[n + 1];
        for (int i = 0; i < n; i++) T[i + 1] = T[i] + time[i];
        long[][] dp = new long[n][k + 1];
        for (long[] row : dp) java.util.Arrays.fill(row, INF);
        dp[0][0] = 0;
        for (int i = 1; i < n; i++)
            for (int j = 0; j <= Math.min(k, i - 1); j++)
                for (int p = 0; p < i; p++) {
                    int used = j - (i - p - 1);
                    if (used < 0 || dp[p][used] >= INF) continue;
                    long cand = dp[p][used] + (long)(position[i] - position[p]) * (T[i] - T[p]);
                    dp[i][j] = Math.min(dp[i][j], cand);
                }
        return (int) dp[n - 1][k];
    }
}

