var minTravelTime = function(l, n, k, position, time) {
    const INF = Infinity;
    const T = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) T[i + 1] = T[i] + time[i];
    const dp = Array.from({length: n}, () => new Array(k + 1).fill(INF));
    dp[0][0] = 0;
    for (let i = 1; i < n; i++)
        for (let j = 0; j <= Math.min(k, i - 1); j++)
            for (let p = 0; p < i; p++) {
                const used = j - (i - p - 1);
                if (used < 0 || dp[p][used] === INF) continue;
                const cand = dp[p][used] + (position[i] - position[p]) * (T[i] - T[p]);
                if (cand < dp[i][j]) dp[i][j] = cand;
            }
    return dp[n - 1][k];
};
